function rq($v,$m){if(!$v)throw new RuntimeException($m);} function q(PDO $d,string $s):array{$r=$d->query($s)->fetchAll(PDO::FETCH_ASSOC);rq(count($r)<=5000,'row_budget');return$r;}
function walk($v,string $path,array &$counts,array &$examples,int $d=0):void{if($d>12||!is_array($v))return;foreach($v as$k=>$x){$p=$path===''?(string)$k:$path.'.'.$k;if(is_array($x)){walk($x,$p,$counts,$examples,$d+1);continue;}if($x===null||is_bool($x))continue;$s=trim((string)$x);if($s==='')continue;if(!preg_match('/(?:name|hotel|country|region|resort|town|place|lat|lon|lng|coord|category|star|key|code|id)$/i',(string)$k)&&!preg_match('/(?:hotel|country|region|resort|geo|source|provider|native|original|catalog)/i',$p))continue;$counts[$p]=($counts[$p]??0)+1;if(!isset($examples[$p]))$examples[$p]=mb_substr($s,0,120,'UTF-8');}}
