try{$root=realpath(getcwd());rq(is_string($root)&&basename($root)==='anytoour.ru','root');require_once $root.(is_file($root.'/data/db-v1.php')?'/data/db-v1.php':'/v2/data/db-v1.php');$db=v2_data_db();$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$db->exec('START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY');$rows=q($db,"SELECT external_hotel_id,evidence_sha256,evidence_json FROM andromeda_hotel_identities WHERE supplier_namespace='andromeda_catalog' AND decision_status='pending' AND local_hotel_id IS NULL ORDER BY CAST(external_hotel_id AS UNSIGNED),external_hotel_id");$db->exec('ROLLBACK');$paths=[];$examples=[];$shapes=[];$samples=[];foreach($rows as$r){$e=json_decode((string)$r['evidence_json'],true,64,JSON_THROW_ON_ERROR);rq(is_array($e),'evidence_shape');$top=array_keys($e);sort($top,SORT_STRING);$shape=implode('|',$top);$shapes[$shape]=($shapes[$shape]??0)+1;walk($e,'',$paths,$examples);if(count($samples)<80){$leaf=[];$dummy=[];walk($e,'',$leaf,$dummy);arsort($leaf);$vals=[];foreach(array_keys($leaf)as$p){$parts=explode('.',$p);$v=$e;foreach($parts as$part){if(!is_array($v)||!array_key_exists($part,$v)){ $v=null; break;} $v=$v[$part];}if(!is_array($v)&&$v!==null&&trim((string)$v)!=='')$vals[$p]=mb_substr(trim((string)$v),0,100,'UTF-8');if(count($vals)>=12)break;}$samples[]=['external_hotel_id'=>(string)$r['external_hotel_id'],'evidence_sha256'=>(string)$r['evidence_sha256'],'top_keys'=>$top,'selected_leafs'=>$vals];}}
arsort($paths);arsort($shapes);$topPaths=[];foreach(array_slice($paths,0,120,true)as$p=>$c)$topPaths[]=['path'=>$p,'count'=>$c,'example'=>$examples[$p]??null];$topShapes=[];foreach(array_slice($shapes,0,40,true)as$s=>$c)$topShapes[]=['top_key_shape'=>$s,'count'=>$c];$out['state']='completed_read_only';$out['pending_total']=count($rows);$out['top_paths']=$topPaths;$out['top_shapes']=$topShapes;$out['samples']=$samples;$out['read_at_utc']=gmdate('c');}catch(Throwable $e){if($db instanceof PDO&&$db->inTransaction())$db->rollBack();$out['error_code']=preg_match('/^[a-z_]{2,100}$/D',$e->getMessage())?$e->getMessage():'sanitized_failure';}
